// Sorts the incoming text into opted out, opted back in, asked for help, or a normal message,
// and writes the one line the owner should see.
const s = $('Your settings').first().json;
const b = $('Text comes in').first().json.body || {};
const from = String(b.From || '').trim();
const to = String(b.To || '').trim();
const text = String(b.Body || '').trim();
const owner = String(s.owner_cell || '').trim();
const biz = String(s.business_name || 'your business').trim();
const media = Number(b.NumMedia) || 0;

// When Advanced Opt-Out handled the keyword, Twilio adds OptOutType (STOP, START or HELP). That is the source of truth.
// Without it, fall back to Twilio's default keyword lists, matched against the whole message.
const twilioType = String(b.OptOutType || '').toUpperCase();
const word = text.toUpperCase();
const STOP = ['STOP', 'STOPALL', 'UNSUBSCRIBE', 'CANCEL', 'END', 'QUIT', 'REVOKE', 'OPTOUT'];
const START = ['START', 'UNSTOP'];
const HELP = ['HELP'];
let kind = 'message';
if (twilioType === 'STOP' || (!twilioType && STOP.includes(word))) kind = 'opted_out';
else if (twilioType === 'START' || (!twilioType && START.includes(word))) kind = 'opted_in';
else if (twilioType === 'HELP' || (!twilioType && HELP.includes(word))) kind = 'help';
const byTwilio = twilioType !== '';

const pretty = n => String(n).replace(/^\+1(\d{3})(\d{3})(\d{4})$/, '($1) $2-$3');
const who = pretty(from);
const quoted = '"' + (text.length > 300 ? text.slice(0, 300) + '...' : text) + '"';

let ownerText = '';
if (kind === 'opted_out') ownerText = who + ' texted ' + quoted + ' and opted out of texts from ' + biz + '.' + (byTwilio ? ' Twilio will block any more texts to them from this number.' : ' Take them off your texting lists.');
if (kind === 'opted_in') ownerText = who + ' texted ' + quoted + ' and can get texts from ' + biz + ' again.';
if (kind === 'help') ownerText = who + ' texted ' + quoted + ' asking for help.' + (byTwilio ? ' Twilio sent them your standard help reply.' : '') + ' A quick call may be worth it.';
const files = media ? media + (media === 1 ? ' photo or file' : ' photos or files') : '';
if (kind === 'message') ownerText = 'Text from ' + who + ': ' + (text ? quoted + (files ? ' plus ' + files : '') : files || '(empty)');

// Never alert the owner about their own texts, and ignore anything that is not a real inbound text.
const isRealText = from !== '' && to !== '';
const fromOwner = from === owner || from === to;
const tellOwner = isRealText && !fromOwner && owner !== '' && (kind !== 'message' || s.forward_other_texts === true);
const crmUrl = String(s.crm_webhook_url || '').trim();
const tellCrm = isRealText && !fromOwner && crmUrl !== '' && (kind === 'opted_out' || kind === 'opted_in');

return [{ json: {
  kind, keyword: word, handled_by_twilio: byTwilio, from, business_number: to, owner, owner_text: ownerText,
  tell_owner: tellOwner, tell_crm: tellCrm, crm_url: crmUrl, message_sid: String(b.MessageSid || ''),
  received_at: new Date().toISOString(),
} }];
